<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/commerce.php';
send_cors_headers();$auth=require_auth();$userId=auth_user_id($auth);$method=$_SERVER['REQUEST_METHOD']??'GET';$db=get_db();
if($method==='GET')json_response(200,['success'=>true,'cart'=>cart_details($userId)]);
if(in_array($method,['POST','PATCH'],true)){$body=get_json_body();$variant=trim((string)($body['variant_id']??''));$quantity=(int)($body['quantity']??0);if($quantity<1||$quantity>20)json_response(422,['success'=>false,'message'=>'Quantity must be between 1 and 20.']);$stmt=$db->prepare('SELECT pv.id,pv.is_active,p.status,v.status AS vendor_status,(i.stock_quantity-i.reserved_quantity) available FROM product_variants pv JOIN products p ON p.id=pv.product_id JOIN vendors v ON v.id=p.vendor_id JOIN inventory_levels i ON i.variant_id=pv.id WHERE pv.id=:id');$stmt->execute(['id'=>$variant]);$stock=$stmt->fetch();if(!$stock||!(int)$stock['is_active']||!in_array($stock['status'],['approved','active'],true)||$stock['vendor_status']!=='active')json_response(422,['success'=>false,'message'=>'This product is not available.']);if((int)$stock['available']<$quantity)json_response(409,['success'=>false,'message'=>'Requested quantity is not available.']);$cart=active_cart($userId);if($method==='POST')$db->prepare('INSERT INTO cart_items (id,cart_id,variant_id,quantity,created_at,updated_at) VALUES (:id,:cart,:variant,:quantity,UTC_TIMESTAMP(),UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE quantity=LEAST(20,quantity+VALUES(quantity)),updated_at=UTC_TIMESTAMP()')->execute(['id'=>uuid_string(),'cart'=>$cart['id'],'variant'=>$variant,'quantity'=>$quantity]);else{$item=trim((string)($body['item_id']??''));$db->prepare('UPDATE cart_items SET quantity=:quantity,updated_at=UTC_TIMESTAMP() WHERE id=:id AND cart_id=:cart AND variant_id=:variant')->execute(['quantity'=>$quantity,'id'=>$item,'cart'=>$cart['id'],'variant'=>$variant]);}json_response(200,['success'=>true,'message'=>'Cart updated.','cart'=>cart_details($userId)]);}
if($method==='DELETE'){$cart=active_cart($userId);$item=trim((string)($_GET['item_id']??''));$stmt=$db->prepare('DELETE FROM cart_items WHERE id=:id AND cart_id=:cart');$stmt->execute(['id'=>$item,'cart'=>$cart['id']]);json_response(200,['success'=>true,'message'=>'Item removed.','cart'=>cart_details($userId)]);}
json_response(405,['success'=>false,'message'=>'Method not allowed.']);
